package wgmodern;
import java.util.*;import java.io.*;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;import net.minecraft.world.phys.Vec3;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;
/** Loads only the original author's external OBJ, once per resource reload. */
public class GemRenderer extends BlockEntityWithoutLevelRenderer {
 public record Triangle(Vec3 a,Vec3 b,Vec3 c,Vec3 normal){}
 private static Map<String,List<Triangle>> model;
 private static final ResourceLocation OBJ=new ResourceLocation("witchinggadgets","models/gems.obj"),WHITE=new ResourceLocation("witchinggadgets","textures/models/white.png");
 public GemRenderer(){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());}
 public static void clear(){model=null;}
 public static Map<String,List<Triangle>> load(){if(model!=null)return model;var result=new HashMap<String,List<Triangle>>();var vertices=new ArrayList<Vec3>();String group="";try(var reader=new BufferedReader(new InputStreamReader(Minecraft.getInstance().getResourceManager().open(OBJ),java.nio.charset.StandardCharsets.UTF_8))){for(String line;(line=reader.readLine())!=null;){var bits=line.trim().split("\\s+");if(bits.length<2)continue;switch(bits[0]){case "v"->vertices.add(new Vec3(Double.parseDouble(bits[1]),Double.parseDouble(bits[2]),Double.parseDouble(bits[3])));case "g","o"->{group=bits[1];result.computeIfAbsent(group,k->new ArrayList<>());}case "f"->{var list=result.computeIfAbsent(group,k->new ArrayList<>());var a=vertex(vertices,bits[1]);for(int i=2;i<bits.length-1;i++){var b=vertex(vertices,bits[i]);var c=vertex(vertices,bits[i+1]);list.add(new Triangle(a,b,c,b.subtract(a).cross(c.subtract(a)).normalize()));}}}}}catch(IOException|RuntimeException ex){org.slf4j.LoggerFactory.getLogger("WitchingGadgets").error("Cannot read external gemstone model",ex);}model=result;return model;}
 private static Vec3 vertex(List<Vec3> vertices,String token){int index=Integer.parseInt(token.split("/")[0]);return vertices.get(index>0?index-1:vertices.size()+index);}
 @Override public void onResourceManagerReload(net.minecraft.server.packs.resources.ResourceManager m){super.onResourceManagerReload(m);clear();}
 @Override public void renderByItem(ItemStack s,ItemDisplayContext display,PoseStack pose,MultiBufferSource buffers,int light,int overlay){pose.pushPose();pose.translate(.5,.4,.5);pose.mulPose(Axis.YP.rotationDegrees(90));pose.mulPose(Axis.ZP.rotationDegrees(22.5f));switch(display){case GUI->{pose.scale(2.5f,2.5f,2.5f);pose.mulPose(Axis.ZP.rotationDegrees(180));pose.translate(-.025,-.14,.2);}case GROUND->pose.scale(2,2,2);case FIRST_PERSON_LEFT_HAND,FIRST_PERSON_RIGHT_HAND->{pose.scale(1,1,-1);pose.translate(.75,.0625,0);}case THIRD_PERSON_LEFT_HAND,THIRD_PERSON_RIGHT_HAND->{pose.scale(1.5f,1.5f,1.5f);pose.translate(.3125,0,0);pose.mulPose(Axis.ZP.rotationDegrees(15));pose.mulPose(Axis.XP.rotationDegrees(5));}default->{}}
 String group=InfusedGem.cut(s)==0?"PointCut_00":"OvalCut_04";var triangles=load().getOrDefault(group,List.of());int color=InfusedGem.color(s);draw(triangles,pose,buffers.getBuffer(RenderType.entityTranslucent(WHITE)),light,overlay,color,.9375f);if(display!=ItemDisplayContext.GUI){pose.pushPose();pose.scale(.875f,.875f,.875f);pose.translate(0,.015625,0);draw(triangles,pose,buffers.getBuffer(RenderType.eyes(WHITE)),LightTexture.FULL_BRIGHT,overlay,0xffffff,1);pose.popPose();}if(s.hasFoil())draw(triangles,pose,buffers.getBuffer(RenderType.entityGlintDirect()),light,overlay,0xffffff,1);pose.popPose();}
 private static void draw(List<Triangle> triangles,PoseStack p,VertexConsumer out,int light,int overlay,int color,float alpha){for(var t:triangles){put(out,p,t.a,t.normal,color,alpha,light,overlay,0,0);put(out,p,t.b,t.normal,color,alpha,light,overlay,1,0);put(out,p,t.c,t.normal,color,alpha,light,overlay,1,1);put(out,p,t.c,t.normal,color,alpha,light,overlay,1,1);}}
 private static void put(VertexConsumer out,PoseStack p,Vec3 v,Vec3 normal,int rgb,float alpha,int light,int overlay,float u,float texv){out.vertex(p.last().pose(),(float)v.x,(float)v.y,(float)v.z).color((rgb>>16&255)/255f,(rgb>>8&255)/255f,(rgb&255)/255f,alpha).uv(u,texv).overlayCoords(overlay).uv2(light).normal(p.last().normal(),(float)normal.x,(float)normal.y,(float)normal.z).endVertex();}
}
